"""Render docs/final_model.md from models/final/config.json and metrics.json.

Every number in the generated page is read from those two files, so the documentation cannot
drift from the trained model. Regenerate with:  python scripts/write_model_summary.py
"""

from sar.config import RISK_BANDS

HEADER = ("<!-- Generated by scripts/write_model_summary.py from models/final/config.json and "
          "models/final/metrics.json. Do not edit by hand. -->")
CUTOFF_ORDER = ("top_10", "top_20", "top_30", "wide_net")


def _p(x: float) -> str:
    return f"{x:.0%}" if round(x * 100) == x * 100 else f"{x:.1%}"


def _f(x: float, d: int = 3) -> str:
    return f"{x:.{d}f}"


def _ci(c: dict) -> str:
    return f"{_f(c['ci95'][0])} to {_f(c['ci95'][1])}"


def _table(head: list[str], rows: list[list[str]]) -> list[str]:
    return ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)] + ["| " + " | ".join(r) + " |" for r in rows]


def render_summary(config: dict, metrics: dict) -> str:
    fin, val = metrics["final"], metrics["final"]["validation"]
    vp = ", ".join(metrics["validation_presentation"])
    cut = config["cutoffs"]
    out = [HEADER, "", "# Final model summary", ""]

    out += ["## Configuration", "",
            f"- **Model:** {config['model']}.",
            f"- **Inputs:** {len(config['features'])} Day {config['cutoff_day']} features. Protected attributes are "
            f"not inputs: {', '.join(config['excluded_protected_features'])}.",
            f"- **Parameters:** " + ", ".join(f"{k}={v}" for k, v in config["params"].items())
            + f"; seed {config['seed']}.",
            f"- **Training presentations:** {', '.join(config['train_presentations'])} "
            f"({metrics['train_rows']:,} rows). **Validation presentation:** {vp} ({metrics['validation_rows']:,} rows).",
            f"- **Data:** `{config['data_file']}`, SHA-256 `{config['data_sha256'][:12]}`.",
            f"- **Versions:** " + ", ".join(f"{k} {v}" for k, v in config["versions"].items()) + ".",
            "- **Inputs used:** " + ", ".join(f"`{f}`" for f in config["features"]) + ".", ""]

    out += ["## Cutoffs", "",
            "All cutoffs are calibrated scores chosen on out-of-fold predictions for the training presentations "
            f"(GroupKFold by presentation). {vp} is never used to choose them.", ""]
    out += _table(["Cutoff", "Rule", "Calibrated score", "Out-of-fold flagged", "Out-of-fold recall",
                   "Out-of-fold precision"],
                  [[k, cut[k]["rule"], _f(cut[k]["score"]), _p(cut[k]["oof_flagged_share"]), _f(cut[k]["oof_recall"]),
                    _f(cut[k]["oof_precision"])] for k in CUTOFF_ORDER])
    out += ["", "## Risk bands", "",
            "Defined once in `sar.config.RISK_BANDS`. Each band starts at a named cutoff above.", ""]
    rows = []
    for i, (band, name) in enumerate(RISK_BANDS):
        low = 0.0 if name is None else cut[name]["score"]
        nxt = RISK_BANDS[i + 1][1] if i + 1 < len(RISK_BANDS) else None
        high = f"to below {_f(cut[nxt]['score'])}" if nxt else "to 1"
        rows.append([band, name or "none (starts at 0)", f"{_f(low)} {high}"])
    out += _table(["Band", "Starts at cutoff", "Calibrated score range"], rows)

    out += ["", f"## Validation results ({vp})", ""]
    out += _table(["Measure", "Raw score", "Calibrated score"], [
        ["ROC-AUC", _f(val["roc_auc"]), _f(val["roc_auc_calibrated"])],
        ["PR-AUC", _f(val["pr_auc"]), _f(val["pr_auc_calibrated"])],
        ["Brier score", _f(val["raw"]["brier"]), _f(val["calibrated"]["brier"])],
        ["Expected calibration error (10 bins)", _f(val["raw"]["ece"]), _f(val["calibrated"]["ece"])],
    ])
    out += ["", f"At-risk prevalence in {vp}: {_f(val['prevalence'])}.", ""]

    out += ["### Main view: capacity ranking", "",
            f"Rank the cohort by calibrated risk and contact the top share. This is how the app flags students.", ""]
    out += _table(["Flagged share", "Students", "Precision", "Recall", "Lift"],
                  [[k, f"{v['flagged']:,}", _f(v["precision"]), _f(v["recall"]), _f(v["lift"], 2)]
                   for k, v in val["capacity"].items()])
    out += ["", "### Second view: fixed score cutoffs", "",
            "Flag anyone at or above a calibrated score set before the cohort arrived.", ""]
    out += _table(["Cutoff", "Calibrated score", f"Flagged in {vp}", "Precision", "Recall", "Lift"],
                  [[k, _f(val["cutoffs"][k]["score"]), _p(val["cutoffs"][k]["flagged_share"]),
                    _f(val["cutoffs"][k]["precision"]), _f(val["cutoffs"][k]["recall"]), _f(val["cutoffs"][k]["lift"], 2)]
                   for k in CUTOFF_ORDER])

    boot = fin["bootstrap_validation"]
    out += ["", f"### Uncertainty ({boot['resamples']:,} bootstrap resamples of {vp}, seed {boot['seed']})", ""]
    out += _table(["Measure", "95% interval"], [
        ["ROC-AUC", _ci(boot["roc_auc"])], ["PR-AUC", _ci(boot["pr_auc"])],
        ["Precision at the top_20 cutoff", _ci(boot["precision_top_20"])],
        ["Recall at the top_20 cutoff", _ci(boot["recall_top_20"])],
    ])

    lopo = fin["leave_one_presentation_out"]
    out += ["", "### Leave one presentation out", "",
            "Model, calibrator and cutoffs refitted with each presentation held out.", ""]
    out += _table(["Held out", "Prevalence", "ROC-AUC", "PR-AUC", "top_20: flagged", "top_20: precision",
                   "top_20: recall", "wide_net: flagged", "wide_net: recall"],
                  [[p, _f(r["prevalence"]), _f(r["roc_auc"]), _f(r["pr_auc"]), _p(r["cutoffs"]["top_20"]["flagged_share"]),
                    _f(r["cutoffs"]["top_20"]["precision"]), _f(r["cutoffs"]["top_20"]["recall"]),
                    _p(r["cutoffs"]["wide_net"]["flagged_share"]), _f(r["cutoffs"]["wide_net"]["recall"])]
                   for p, r in lopo.items()])

    fair = fin["fairness_validation"]
    out += ["", f"### Fairness at the {fair['cutoff']} cutoff ({vp})", "",
            "Protected attributes are read from the matrix for this check only; they are not model inputs.", ""]
    rows = [[f"{col}: {g}", f"{s['n']:,}", f"{s['at_risk_n']:,}", _p(s["flag_rate"]), _f(s["recall"])]
            for col, groups in fair["groups"].items() for g, s in groups.items()]
    out += _table(["Group", "Students", "At risk", "Flag rate", "Recall"], rows)
    out += [""]
    out += _table(["Gap", "Point", "95% interval", "Interval excludes zero"],
                  [[k.replace("_", " "), f"{v['point']:+.3f}", _ci(v), "yes" if v["ci_excludes_zero"] else "no"]
                   for k, v in fair["gaps"].items()])

    out += ["", "### Comparison models (same split, same procedure)", ""]
    rows = [["final (24 inputs)", _f(val["roc_auc"]), _f(val["pr_auc"]), _f(val["capacity"]["20%"]["precision"]),
             _f(val["capacity"]["20%"]["recall"])]]
    rows += [[name.replace("_", " "), _f(c["validation"]["roc_auc"]), _f(c["validation"]["pr_auc"]),
              _f(c["validation"]["capacity"]["20%"]["precision"]), _f(c["validation"]["capacity"]["20%"]["recall"])]
             for name, c in metrics["comparisons"].items()]
    out += _table(["Model", "ROC-AUC", "PR-AUC", "Precision, top 20%", "Recall, top 20%"], rows)

    shares = [r["cutoffs"]["top_20"]["flagged_share"] for r in lopo.values()]
    prev = [r["prevalence"] for r in lopo.values()]
    out += ["", "## Limitations", "",
            f"- **Fixed cutoffs do not flag a stable share.** At-risk prevalence differs between presentations "
            f"({_f(min(prev))} to {_f(max(prev))}), so the top_20 cutoff flags between {_p(min(shares))} and "
            f"{_p(max(shares))} of a held-out presentation, and {_p(val['cutoffs']['top_20']['flagged_share'])} of {vp}. "
            "This is why the app flags by capacity ranking.",
            f"- **{vp} is a validation set, not an untouched test set.** It was used earlier to compare model types. "
            "Its figures are therefore somewhat optimistic; the leave-one-presentation-out table shows the spread.",
            "- **Calibration folds.** The calibrator is fitted on out-of-fold scores from models trained on two of "
            "the three training presentations, then applied to the model trained on all three.",
            "- **Fairness.** Recall and flag rate differ by gender and age band at the same cutoff (table above), "
            "although protected attributes are not inputs.",
            ""]
    return "\n".join(out)
